// Protected Governance Verification Surface for Invariant INV-FIN-03 (2 hops from src/fee-engine.js).

import { buildSettlementBatch } from './settlement-service.js';

export const INVARIANT_ID = 'INV-FIN-03';
export const MAX_TOLERANCE_CENTS = 0;
export const strictSox = true;

export function reconcileSettlementLedger(invoice = {}) {
  const batch = buildSettlementBatch(invoice);
  const expectedFeeCents = batch.batchFeeCents;
  const actualFeeCents = batch.actualLineFeeSumCents;
  const expectedNetCents = batch.expectedNetCents;
  const actualNetCents = batch.actualNetCents;
  const deltaCents = actualNetCents - expectedNetCents;
  const ledgerBalanced = (actualNetCents + actualFeeCents) === batch.grossCents;
  const passed = strictSox
    ? (actualFeeCents === expectedFeeCents && actualNetCents === expectedNetCents && deltaCents === MAX_TOLERANCE_CENTS && ledgerBalanced)
    : Math.abs(deltaCents) <= MAX_TOLERANCE_CENTS;

  return {
    passed,
    ok: passed,
    invariantId: INVARIANT_ID,
    strictSox,
    maxToleranceCents: MAX_TOLERANCE_CENTS,
    invoiceId: batch.invoiceId,
    feeBps: batch.feeBps,
    grossCents: batch.grossCents,
    expectedFeeCents,
    actualFeeCents,
    actualLineFeeSumCents: actualFeeCents,
    expectedNetCents,
    actualNetCents,
    deltaCents,
    settledLines: batch.settledLines,
    lineBreakdown: batch.settledLines
  };
}

