// Scoped to Work Order WO-103 (disjoint from WO-101 and WO-102).

export function listTenantInvoices(items = [], cursor = null, pageSize = 25) {
  const safeItems = Array.isArray(items) ? items : [];
  const boundedLimit = Math.max(1, Math.min(100, Math.trunc(Number(pageSize) || 25)));
  const startIndex = cursor
    ? Math.max(0, safeItems.findIndex((item) => String(item?.id ?? '') === String(cursor)) + 1)
    : 0;
  const pageItems = safeItems.slice(startIndex, startIndex + boundedLimit);
  const hasMore = startIndex + boundedLimit < safeItems.length;
  const tailItem = pageItems.length > 0 ? pageItems[pageItems.length - 1] : null;

  return {
    items: pageItems,
    pageSize: boundedLimit,
    hasMore,
    nextToken: hasMore && tailItem ? String(tailItem.id ?? '') : null
  };
}

