// Acme Legacy Billing - Processor Fee Engine (src/fee-engine.js)
// Verified remediation for WO-101: integer basis-point largest-remainder cent distribution (INV-FIN-03).

export function calculateBatchFeeCents(grossCents, feeBps = 250) {
  const safeGross = Math.round(Number(grossCents) || 0);
  const safeBps = Number.isFinite(Number(feeBps)) ? Number(feeBps) : 250;
  return Math.round((safeGross * safeBps) / 10000);
}

export function allocateInvoiceLineFees(lineAmountsCents, feeBps = 250) {
  const safeLines = Array.isArray(lineAmountsCents) ? lineAmountsCents : [];
  if (safeLines.length === 0) {
    return [];
  }
  const safeBps = Math.round(Number.isFinite(Number(feeBps)) ? Number(feeBps) : 250);
  const amounts = safeLines.map((entry) => (
    typeof entry === 'number'
      ? Math.round(entry)
      : Math.round(Number(entry?.amountCents ?? entry?.grossCents ?? entry?.cents ?? entry?.amount ?? 0) || 0)
  ));

  const grossCents = amounts.reduce((sum, amount) => sum + amount, 0);
  const targetBatchFeeCents = calculateBatchFeeCents(grossCents, safeBps);

  const baseAllocations = amounts.map((amountCents, lineIndex) => {
    const scaledNumerator = amountCents * safeBps;
    const floorFeeCents = Math.floor(scaledNumerator / 10000);
    const remainderBps = ((scaledNumerator % 10000) + 10000) % 10000;
    return {
      lineIndex,
      amountCents,
      floorFeeCents,
      remainderBps
    };
  });

  const floorFeeSumCents = baseAllocations.reduce((sum, item) => sum + item.floorFeeCents, 0);
  const residualCents = targetBatchFeeCents - floorFeeSumCents;

  const rankedIndices = baseAllocations
    .map((item) => item.lineIndex)
    .sort((idxA, idxB) => {
      const a = baseAllocations[idxA];
      const b = baseAllocations[idxB];
      if (b.remainderBps !== a.remainderBps) {
        return b.remainderBps - a.remainderBps;
      }
      if (b.amountCents !== a.amountCents) {
        return b.amountCents - a.amountCents;
      }
      return a.lineIndex - b.lineIndex;
    });

  const carrySet = new Set(rankedIndices.slice(0, Math.max(0, residualCents)));

  return baseAllocations.map((item) => {
    const feeCents = item.floorFeeCents + (carrySet.has(item.lineIndex) ? 1 : 0);
    const netCents = item.amountCents - feeCents;
    return {
      lineIndex: item.lineIndex,
      amountCents: item.amountCents,
      grossCents: item.amountCents,
      feeCents,
      netCents
    };
  });
}

