import { errorEnvelope } from '@krusch/toolkit/http';
import { getSharedUsersStore } from '../../../../lib/users-service.js';

export function createUserItemHandlers(store = getSharedUsersStore()) {
  async function resolveId(context) {
    const resolvedParams = await Promise.resolve(context?.params);
    return resolvedParams?.id;
  }

  async function GET(_request, context) {
    const id = await resolveId(context);
    const envelope = store.getUserById(id);
    const status = envelope.ok ? 200 : envelope.error?.code === 'USER_NOT_FOUND' ? 404 : 400;
    return Response.json(envelope, { status });
  }

  async function PATCH(request, context) {
    const id = await resolveId(context);
    let body = null;
    try {
      body = await request.json();
    } catch {
      const badJson = errorEnvelope(
        'INVALID_JSON_BODY',
        'Request body must be valid JSON.',
        null,
        'users.route.patch'
      );
      return Response.json(badJson, { status: 400 });
    }

    const envelope = store.updateUserById(id, body);
    const status = envelope.ok ? 200 : envelope.error?.code === 'USER_NOT_FOUND' ? 404 : 400;
    return Response.json(envelope, { status });
  }

  async function DELETE(_request, context) {
    const id = await resolveId(context);
    const envelope = store.deleteUserById(id);
    const status = envelope.ok ? 200 : envelope.error?.code === 'USER_NOT_FOUND' ? 404 : 400;
    return Response.json(envelope, { status });
  }

  return { GET, PATCH, DELETE };
}

const defaultItemHandlers = createUserItemHandlers();
export const GET = defaultItemHandlers.GET;
export const PATCH = defaultItemHandlers.PATCH;
export const DELETE = defaultItemHandlers.DELETE;

