import { createAuth } from '@krusch/toolkit/auth';
import { s, validateSchema } from '@krusch/toolkit/schema';

export const UserMutationSchema = s.object({
  firstname: s.string({ minLength: 1, maxLength: 80 }),
  lastname: s.string({ minLength: 1, maxLength: 80 }),
  email: s.string({ format: 'email' }),
  age: s.integer({ min: 0, max: 130 }),
  location: s.string({ minLength: 1, maxLength: 120 })
});

export const LocationFilterSchema = s.object({
  location: s.string({ minLength: 1, maxLength: 120 })
});

export function createOperatorSessionAuth(secret) {
  return createAuth({
    secret,
    cookieName: 'pdo_nextjs_session',
    expiresIn: '12h'
  });
}

export function validateUserMutationInput(payload) {
  return validateSchema(UserMutationSchema, payload, {
    coerce: true,
    stripUnknown: true,
    tool: 'users.schema.mutation'
  });
}

export function validateLocationQuery(payload) {
  return validateSchema(LocationFilterSchema, payload, {
    coerce: true,
    stripUnknown: true,
    tool: 'users.schema.filter'
  });
}

