import { okEnvelope, errorEnvelope } from '@krusch/toolkit/http';
import { paginateItems } from '@krusch/toolkit/pagination';
import { createAuditLog } from '@krusch/toolkit/audit-log';
import { loadUsersPortConfig } from './config.js';
import { openUsersDatabase } from './db.js';
import {
  createOperatorSessionAuth,
  validateUserMutationInput,
  validateLocationQuery
} from './security.js';

export function createUsersStore(overrides = {}) {
  const baseCfg = loadUsersPortConfig();
  const cfg = { ...baseCfg, ...overrides };
  const conn = openUsersDatabase(cfg.dbPath);
  const auth = createOperatorSessionAuth(cfg.sessionSecret);
  const auditLog = createAuditLog({
    sqlitePath: '',
    hmacSecret: cfg.auditHmacSecret,
    tool: 'users.audit'
  });

  function createUser(rawPayload) {
    const check = validateUserMutationInput(rawPayload);
    if (!check.ok) {
      return check;
    }

    const input = check.data;
    const res = conn.run(
      `INSERT INTO users (firstname, lastname, email, age, location)
       VALUES (?, ?, ?, ?, ?)`,
      [input.firstname, input.lastname, input.email, input.age, input.location]
    );

    const created = conn.queryOne(
      'SELECT id, firstname, lastname, email, age, location, created_at FROM users WHERE id = ?',
      [res.lastInsertRowid]
    );

    auditLog.append({
      actor: 'nextjs-users-service',
      action: 'users.create',
      resource: `users/${res.lastInsertRowid}`,
      outcome: 'ALLOWED',
      metadata: { email: input.email, location: input.location }
    });

    return okEnvelope(
      'users.create',
      `Created user #${res.lastInsertRowid} (${input.firstname} ${input.lastname}).`,
      { user: created }
    );
  }

  function listUsers({ cursor = '', limit = 25, location = '' } = {}) {
    let rows = [];
    const trimmedLoc = String(location || '').trim();

    if (trimmedLoc.length > 0) {
      const filterCheck = validateLocationQuery({ location: trimmedLoc });
      if (!filterCheck.ok) {
        return filterCheck;
      }
      rows = conn.query(
        `SELECT id, firstname, lastname, email, age, location, created_at
         FROM users
         WHERE LOWER(location) = LOWER(?)
         ORDER BY id ASC`,
        [filterCheck.data.location]
      );
    } else {
      rows = conn.query(
        `SELECT id, firstname, lastname, email, age, location, created_at
         FROM users
         ORDER BY id ASC`
      );
    }

    return paginateItems(rows, {
      cursor,
      limit,
      secret: cfg.cursorSecret,
      scope: trimmedLoc ? `users:loc:${trimmedLoc.toLowerCase()}` : 'users:all',
      sortField: 'id',
      idField: 'id',
      direction: 'asc',
      tool: 'users.list'
    });
  }

  function getUserById(rawId) {
    const id = Number(rawId);
    if (!Number.isInteger(id) || id <= 0) {
      return errorEnvelope('INVALID_USER_ID', 'User ID must be a positive integer.', { id: rawId }, 'users.get');
    }

    const user = conn.queryOne(
      'SELECT id, firstname, lastname, email, age, location, created_at FROM users WHERE id = ?',
      [id]
    );

    if (!user) {
      return errorEnvelope('USER_NOT_FOUND', `User #${id} was not found.`, { id }, 'users.get');
    }

    return okEnvelope('users.get', `Loaded user #${id}.`, { user });
  }

  function updateUserById(rawId, rawPayload) {
    const id = Number(rawId);
    if (!Number.isInteger(id) || id <= 0) {
      return errorEnvelope('INVALID_USER_ID', 'User ID must be a positive integer.', { id: rawId }, 'users.update');
    }

    const check = validateUserMutationInput(rawPayload);
    if (!check.ok) {
      return check;
    }

    const existing = conn.queryOne('SELECT id FROM users WHERE id = ?', [id]);
    if (!existing) {
      return errorEnvelope('USER_NOT_FOUND', `User #${id} was not found.`, { id }, 'users.update');
    }

    const input = check.data;
    // Remediates legacy update-single.php bug: primary key `id` is never mutable in SET clause
    conn.run(
      `UPDATE users
       SET firstname = ?, lastname = ?, email = ?, age = ?, location = ?
       WHERE id = ?`,
      [input.firstname, input.lastname, input.email, input.age, input.location, id]
    );

    const updated = conn.queryOne(
      'SELECT id, firstname, lastname, email, age, location, created_at FROM users WHERE id = ?',
      [id]
    );

    auditLog.append({
      actor: 'nextjs-users-service',
      action: 'users.update',
      resource: `users/${id}`,
      outcome: 'ALLOWED',
      metadata: { email: input.email, location: input.location }
    });

    return okEnvelope('users.update', `Updated user #${id}.`, { user: updated });
  }

  function deleteUserById(rawId) {
    const id = Number(rawId);
    if (!Number.isInteger(id) || id <= 0) {
      return errorEnvelope('INVALID_USER_ID', 'User ID must be a positive integer.', { id: rawId }, 'users.delete');
    }

    const res = conn.run('DELETE FROM users WHERE id = ?', [id]);
    if (res.changes === 0) {
      return errorEnvelope('USER_NOT_FOUND', `User #${id} was not found.`, { id }, 'users.delete');
    }

    auditLog.append({
      actor: 'nextjs-users-service',
      action: 'users.delete',
      resource: `users/${id}`,
      outcome: 'ALLOWED',
      metadata: { deletedId: id }
    });

    return okEnvelope('users.delete', `Deleted user #${id}.`, { deletedId: id });
  }

  function verifyAudit() {
    return auditLog.verify();
  }

  function close() {
    auditLog.close?.();
    conn.close();
  }

  return Object.freeze({
    auth,
    createUser,
    listUsers,
    getUserById,
    updateUserById,
    deleteUserById,
    verifyAudit,
    close
  });
}

let singletonStore = null;

export function getSharedUsersStore() {
  if (!singletonStore) {
    singletonStore = createUsersStore();
  }
  return singletonStore;
}
